local ("getPanelConfig").packageManager, nametopath = "fgui.base.packageManager", "getPanelConfig"
function include_fgui(fileName)
	local path = nametopath[fileName]
	if path then
		return require_ex(path)
	end
	local suffix = string.sub(fileName, -5, -1)
	local viewName = string.sub(fileName, 1, -6)
	local panelData = getPanelConfig(viewName)
	if not panelData then
		return require_ex(fileName)
	end
	if suffix == "Proxy" and panelData.useBaseProxy then
		local proxyPath = "fgui.base.baseProxy"
		return require_ex(proxyPath)
	end
	local moduleName = panelData.moduleName or panelData.pkg
	local _viewName = panelData.panelName or viewName
	local className = string.format("%s%s", _viewName, suffix)
	local viewPath
	if moduleName then
		viewPath = string.format("fgui.views.%s.%s", moduleName, className)
	else
		viewPath = string.format("fgui.views.%s", className)
	end
	local ViewCls = require_ex(viewPath)
	return ViewCls
end
